// Browser code controls presentation. Permissions are enforced in app/lib/backend.js.
const main = document.querySelector('#main');
let csrf = '';
let user;
const dashboardPath = role => role === 'admin' ? '/admin' : role === 'coordinator' ? '/coordinator' : '/patient';
const isStaff=()=>['admin','coordinator'].includes(user?.role);
const adminHospital=()=>sessionStorage.getItem('adminHospital')||'';
const visiblePages=()=>user.role==='admin'?[['/admin','All hospitals'],...coordinatorPages]:coordinatorPages.filter(([path])=>path!=='/coordinator/directory');
let filters = { search:'', pathway:'all', owner:'all' };
let selectedCase = null;
let insuranceTimer;
const coordinatorPages=[['/coordinator','Overview'],['/coordinator/cases','Active cases'],['/coordinator/new','New discharge'],['/coordinator/access','Patient access'],['/coordinator/insurance','Insurance desk'],['/coordinator/alerts','Alerts and queues'],['/coordinator/simulator','What-if simulator'],['/coordinator/appointments','Doctor appointments'],['/coordinator/directory','Hospitals and doctors'],['/coordinator/case-history','Case history'],['/coordinator/help','Help desk'],['/coordinator/history','Previous cases'],['/coordinator/integration','Mock hospital interface']];
const esc = value => String(value).replace(/[&<>"']/g, x => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const time = value => new Date(value).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});
const statusLabels = { complete:'Complete', processing:'In progress', pending:'Pending', not_applicable:'Not required', on_hold:'On hold' };

async function api(path, options = {}) {
  const response = await fetch(path, { ...options, headers: { 'Content-Type':'application/json', 'X-DischargeFlow':'1', 'X-CSRF-Token':csrf, ...(user?.role==='admin'&&adminHospital()&&!path.startsWith('/api/admin/')&&!['/api/me','/api/logout'].includes(path)?{'X-Hospital-Id':adminHospital()}:{}) } });
  const data = await response.json();
  if (!response.ok) {
    const error = new Error(data.error || 'Unable to load.'); error.status = response.status; error.passwordChange = !!data.password_change_required; throw error;
  }
  return data;
}

function login(message = '') {
  clearInterval(insuranceTimer);
  user = null; csrf = '';
  if (location.pathname !== '/login') history.replaceState(null, '', '/login');
  document.title = 'Sign in — DischargeFlow';
  main.innerHTML = `<section class="login-layout">
    <div class="intro"><p class="eyebrow">A CLEARER PATH HOME</p><h1>Every step.<br>One shared view.</h1><p class="lede">Connect the people behind a discharge. Know what is complete, what is pending, and what comes next.</p>
    <div class="journey" aria-label="Example discharge stages"><span>01 <b>Documentation</b></span><span>02 <b>Pharmacy</b></span><span>03 <b>Billing</b></span><span>04 <b>Final checks</b></span></div>
    <p class="intro-note">Separate workspaces for platform admins, hospital coordinators, patients and relatives.</p></div>
    <section class="login-card" aria-labelledby="login-title"><span class="small-icon">↗</span><p class="eyebrow">WELCOME TO DISCHARGEFLOW</p><h2 id="login-title">Sign in to your workspace</h2><p class="muted">Your hospital account determines what you can access.</p>
    <form id="login-form"><label for="email">Staff / patient ID or email</label><input id="email" name="email" type="text" autocomplete="username" placeholder="For example: cedar.staff" maxlength="254" required>
    <label for="password">Password</label><input id="password" name="password" type="password" autocomplete="current-password" maxlength="256" required>
    <p id="login-error" class="error" role="alert">${esc(message)}</p><button class="primary" type="submit">Sign in <span>→</span></button></form>
    <div class="access-note"><strong>Access is assigned by the hospital</strong><p>Patients and relatives can see only their linked case. For account help, contact your coordinator.</p></div><p class="demo-note">Prototype accounts use fictional information. No hospital connection is active.</p></section></section>`;
  document.querySelector('#login-form').addEventListener('submit', async event => {
    event.preventDefault(); const button = event.target.querySelector('button'); button.disabled = true; button.textContent = 'Signing in…';
    try {
      const result = await api('/api/login', { method:'POST', body:JSON.stringify({email:event.target.email.value,password:event.target.password.value}) });
      csrf = result.csrf; user = result.user; sessionStorage.removeItem('adminHospital');sessionStorage.removeItem('adminHospitalName');location.assign(user.must_change?'/change-password':dashboardPath(user.role));
    } catch (error) { document.querySelector('#login-error').textContent = error.message; }
    finally { button.disabled = false; button.innerHTML = 'Sign in <span>→</span>'; }
  });
}

function shell(title, subtitle, body) {
  clearInterval(insuranceTimer);
  document.title=title+' — DischargeFlow';
  const staff=isStaff();
  const active=visiblePages().find(([path])=>location.pathname===path)?.[1]||'Workspace';
  const register=staff&&['/coordinator','/coordinator/cases','/coordinator/alerts','/coordinator/history'].includes(location.pathname);
  main.innerHTML = `<section class="workspace ${staff?'coordinator-workspace':''}">${staff?`<button id="workspace-menu" class="secondary workspace-menu" aria-expanded="false" aria-controls="workspace-sidebar">☰ Menu <span>${esc(active)}</span></button><aside id="workspace-sidebar" class="workspace-sidebar"><div class="sidebar-inner"><p class="eyebrow">HOSPITAL WORKSPACE</p><p class="sidebar-title">${user.role==='admin'?'Platform administration':'Discharge coordination'}</p><nav class="page-nav" aria-label="Coordinator pages">${visiblePages().map(([path,label])=>`<a href="${path}" ${location.pathname===path?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="sidebar-note">${user.role==='admin'?'Admin access · all hospitals':esc(user.hospital_name||'Assigned hospital')}<br>Fictional records</div></div></aside>`:''}<div class="workspace-content"><div class="workspace-header"><div><p class="eyebrow">${user.role==='admin'?'PLATFORM ADMIN · ALL HOSPITALS':staff?'HOSPITAL COORDINATOR':'PATIENT AND FAMILY WORKSPACE'}</p><h1>${title}</h1><p class="role-badge ${user.role==='admin'?'admin-badge':''}">${user.role==='admin'?'ADMIN · All-hospital oversight':staff?'COORDINATOR · '+esc(user.hospital_name||'Assigned hospital'):'PATIENT / RELATIVE · Linked admission only'}</p>${user.role==='admin'&&location.pathname!=='/admin'?'<p class="scope-note">Operational view: '+esc(sessionStorage.getItem('adminHospitalName')||'All hospitals')+' · <a href="/admin">Choose hospital</a></p>':''}<p class="muted">${subtitle}</p></div><div class="header-tools">${register?'<a href="/coordinator/new" class="primary action-link">+ Register discharge</a>':''}<div class="account"><span>${esc(user.name)}</span><button id="logout" class="secondary">Sign out</button></div></div></div>${body}</div></section>`;
  document.querySelector('#logout').addEventListener('click', async () => {
    try { await api('/api/logout',{method:'POST',body:'{}'}); sessionStorage.removeItem('adminHospital');sessionStorage.removeItem('adminHospitalName');location.replace('/login'); } catch (error) { showError(error); }
  });
  if(staff){const button=document.querySelector('#workspace-menu');const workspace=document.querySelector('.coordinator-workspace');const close=()=>{workspace.classList.remove('nav-open');button.setAttribute('aria-expanded','false');};button.onclick=()=>{const open=workspace.classList.toggle('nav-open');button.setAttribute('aria-expanded',String(open));};workspace.addEventListener('keydown',event=>{if(event.key==='Escape'&&workspace.classList.contains('nav-open')){close();button.focus();}});}
}

function tasksMarkup(tasks, patient = false) {
  return `<ol class="timeline">${tasks.map(task => `<li class="${esc(task.status)}"><span class="step-marker">${task.status === 'complete' ? '✓' : task.status === 'not_applicable' ? '–' : Number(task.position)+1}</span><div><strong>${esc(task.label)}</strong><p>${patient ? (task.status === 'on_hold' ? 'This step is on hold. Please contact your coordinator for an update.' : task.status === 'processing' ? 'The hospital team is working on this step.' : task.status === 'pending' ? 'This step has not been marked complete.' : task.status === 'not_applicable' ? 'This step does not apply to your pathway.' : 'This step has been completed.') : esc(task.owner)}</p></div><span class="badge ${esc(task.status)}">${statusLabels[task.status]}</span></li>`).join('')}</ol>`;
}

async function dashboard() {
  if (isStaff()) {
    if(location.pathname==='/admin')return adminPage();
    if (location.pathname !== '/coordinator/cases') return coordinatorPage();
    const {cases} = await api('/api/cases');
    document.title = 'Coordinator dashboard — DischargeFlow';
    shell('Active discharge cases', 'Search current cases, update tasks and record departure.', `
      <section class="operations-panel" aria-labelledby="case-list-title"><div class="section-heading"><h2 id="case-list-title">Discharge cases</h2><button id="refresh" class="secondary">Refresh statuses ↻</button></div>
      <form id="filters" class="filter-bar" role="search"><div><label for="case-search">Search cases</label><input type="search" id="case-search" placeholder="Case ID, patient or ward" value="${esc(filters.search)}"></div><div><label for="pathway">Payment pathway</label><select id="pathway"><option value="all">All pathways</option><option value="cash">Self pay</option><option value="insured">Cashless insured</option></select></div><div><label for="owner">Pending department</label><select id="owner"><option value="all">All departments</option>${[...new Set(cases.flatMap(c=>c.tasks.map(t=>t.owner)))].sort().map(owner=>`<option value="${esc(owner)}">${esc(owner)}</option>`).join('')}</select></div><button type="button" class="secondary" id="clear-filters">Clear filters</button></form>
      <p class="muted refresh-time">Retrieved at ${time(new Date())}. Elapsed time is since medical clearance, not active processing time.</p><div id="case-results"></div></section>
      <aside class="notice"><strong>Working case overview</strong><p>Create cases, update tasks and answer patient questions. Explainable demo alerts are available; the what-if simulator compares hypothetical capacity changes. No hospital feed is connected.</p></aside>
      <dialog id="case-dialog" aria-labelledby="detail-title"></dialog><dialog id="new-case-dialog" aria-labelledby="new-case-title"></dialog>`);
    document.querySelector('#pathway').value = filters.pathway;
    document.querySelector('#owner').value = filters.owner;
    const pending = c => c.tasks.filter(t=>!['complete','not_applicable'].includes(t.status));
    const renderResults = () => {
      const search = filters.search.trim().toLowerCase();
      const visible = cases.filter(c => (!search || `${c.id} ${c.display_name} ${c.ward}`.toLowerCase().includes(search)) && (filters.pathway==='all' || c.pathway===filters.pathway) && (filters.owner==='all' || pending(c).some(t=>t.owner===filters.owner)));
      document.querySelector('#case-results').innerHTML = `<p class="result-count" role="status">${visible.length} of ${cases.length} cases shown</p>${visible.length ? `<div class="table-scroll"><table class="case-table"><thead><tr><th scope="col">Case and patient</th><th scope="col">Ward</th><th scope="col">Pathway</th><th scope="col">Outstanding work</th><th scope="col">Elapsed</th><th scope="col">Action</th></tr></thead><tbody>${visible.map(c => {const remaining=pending(c);return `<tr><td><strong>${esc(c.id)}</strong><span>${esc(c.display_name)}</span><span>${esc(c.hospital_name||'')}</span></td><td>${esc(c.ward)}</td><td>${c.pathway==='insured'?'Cashless insured':'Self pay'}</td><td><strong>${remaining.length} tasks remaining</strong><span>${esc([...new Set(remaining.map(t=>t.owner))].join(', ') || 'Await final confirmation')}</span></td><td>${Math.max(0,Math.floor((Date.now()-Date.parse(c.cleared_at))/60000))} min</td><td><button class="secondary view-case" data-case="${esc(c.id)}" aria-label="View case ${esc(c.id)}">View case →</button></td></tr>`;}).join('')}</tbody></table></div>` : '<div class="empty-state"><h3>No matching cases</h3><p>Try another search or clear the filters.</p></div>'}`;
      document.querySelectorAll('.view-case').forEach(button=>button.onclick=()=>openCase(button.dataset.case));
    };
    const openCase = async id => {
      try {
        const result=await api('/api/cases'); selectedCase=result.cases.find(c=>c.id===id);
        const {events}=await api(`/api/cases/${encodeURIComponent(id)}/history`);
        const dialog=document.querySelector('#case-dialog');
        dialog.innerHTML=`<div class="detail-heading"><div><p class="eyebrow">CASE ${esc(selectedCase.id)}</p><h2 id="detail-title">${esc(selectedCase.display_name)}</h2><p class="muted">${esc(selectedCase.ward)} · ${selectedCase.pathway==='insured'?'Cashless insured':'Self pay'}</p></div><button class="secondary" id="close-detail">Close</button></div><p class="detail-cleared">Documentation and pharmacy can run in parallel. Billing follows both, then insurance if applicable, then final checks. Completing tasks never replaces authorised departure confirmation.</p><div class="task-editor">${selectedCase.tasks.map(t=>`<section class="task-edit"><div><strong>${esc(t.label)}</strong><span class="badge ${esc(t.status)}">${statusLabels[t.status]}</span><p class="muted">${esc(t.owner)} · Updated ${esc(new Date(t.updated_at).toLocaleString())}</p>${t.hold_reason?`<p class="hold-note">Hold: ${esc(t.hold_reason)}</p>`:''}</div>${!['complete','not_applicable'].includes(t.status)?`<form class="task-action" data-position="${t.position}"><label for="note-${t.position}">Operational note${t.status==='on_hold'?'':' or hold reason'}</label><input id="note-${t.position}" name="note" maxlength="500" placeholder="Required when placing on hold"><div class="action-buttons">${t.status==='on_hold'?'<button name="action" value="resume" class="secondary">Resume</button>':`${t.status==='pending'?'<button name="action" value="start" class="secondary">Start work</button>':'<button name="action" value="complete" class="secondary">Mark complete</button>'}<button name="action" value="hold" class="secondary">Place on hold</button>`}</div><p class="error" role="alert"></p></form>`:''}</section>`).join('')}</div>${selectedCase.tasks.every(t=>['complete','not_applicable'].includes(t.status))?'<section class="departure-form"><h3>Record actual departure</h3><p class="muted">Only record this after authorised staff confirm departure and the patient has actually left. The case will remain in Previous cases.</p><form id="departure-form"><label class="checkbox"><input name="confirmed" type="checkbox" required> Authorised departure is confirmed and the patient has left.</label><label for="departure-note">Optional operational note</label><input id="departure-note" name="note" maxlength="500"><p class="error" role="alert"></p><button class="secondary">Record departure now</button></form></section>':''}${insurancePanel(selectedCase,true)}<section class="history"><h3>Change history</h3>${events.length?`<ol>${events.map(e=>`<li><strong>${esc(e.action.replaceAll('_',' '))}</strong>${e.position!==null?' · '+esc(selectedCase.tasks[e.position].label):''}<p>${esc(e.actor)} · ${esc(new Date(e.occurred_at).toLocaleString())}</p>${e.note?`<p>${esc(e.note)}</p>`:''}</li>`).join('')}</ol>`:'<p class="muted">No new changes recorded. Existing seeded stages are starting snapshots; earlier actions were not recorded.</p>'}</section>`;
        bindInsuranceReceipt(selectedCase,()=>openCase(id));
        document.querySelector('#close-detail').onclick=()=>{dialog.close();dashboard().catch(showError);};
        dialog.oncancel=()=>{dashboard().catch(showError);};
        dialog.querySelectorAll('.task-action').forEach(form=>form.onsubmit=async event=>{
          event.preventDefault();const action=event.submitter.value;const position=Number(form.dataset.position);const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);
          try{await api(`/api/cases/${encodeURIComponent(id)}/tasks`,{method:'POST',body:JSON.stringify({position,action,note:form.note.value,expected_updated_at:selectedCase.tasks[position].updated_at})});await openCase(id);}
          catch(error){form.querySelector('.error').textContent=error.message;buttons.forEach(b=>b.disabled=false);}
        });
        const departure=document.querySelector('#departure-form');
        if(departure)departure.onsubmit=async event=>{event.preventDefault();const button=departure.querySelector('button');button.disabled=true;try{await api(`/api/cases/${encodeURIComponent(id)}/departure`,{method:'POST',body:JSON.stringify({confirmed:departure.confirmed.checked,note:departure.note.value,departed_at:new Date().toISOString()})});dialog.close();await dashboard();}catch(error){departure.querySelector('.error').textContent=error.message;button.disabled=false;}};
        if(!dialog.open)dialog.showModal();
      }catch(error){showError(error);}
    };


    document.querySelector('#filters').onsubmit=event=>event.preventDefault();
    document.querySelector('#case-search').oninput=event=>{filters.search=event.target.value;renderResults();};
    for(const id of ['pathway','owner']) document.querySelector('#'+id).onchange=event=>{filters[id]=event.target.value;renderResults();};
    document.querySelector('#clear-filters').onclick=()=>{filters={search:'',pathway:'all',owner:'all'};document.querySelector('#case-search').value='';document.querySelector('#pathway').value='all';document.querySelector('#owner').value='all';renderResults();};
    renderResults();
    document.querySelector('#refresh').onclick = () => dashboard().catch(showError);
  } else {
    document.title = 'Your discharge progress — DischargeFlow';
    const {case:c} = await api('/api/my-case');
    const applicable = c.tasks.filter(t=>t.status!=='not_applicable'); const done = applicable.filter(t=>t.status==='complete').length;
    shell('Your discharge progress', c.departed_at?'Departure recorded '+new Date(c.departed_at).toLocaleString():'Follow the remaining steps with your hospital team.', `
      <div id="insurance-notice" role="status">${insurancePanel(c)}</div><div class="patient-layout"><article class="case-card" id="patient-progress"><div class="case-top"><div><span class="eyebrow">${esc(c.id)}</span><h2>${esc(c.display_name)}</h2><p class="muted">${esc(c.ward)}</p></div><span class="pathway">${done} of ${applicable.length} steps complete</span></div>${tasksMarkup(c.tasks,true)}<div class="case-bottom">Latest recorded task update ${time(c.tasks.map(t=>t.updated_at).sort().at(-1))}</div></article>
      <aside><div class="help-card"><p class="eyebrow">WHAT HAPPENS NEXT</p><h2>${esc(c.tasks.find(t=>!['complete','not_applicable'].includes(t.status))?.label || 'Await final confirmation')}</h2><p>These steps show recorded progress. Some work can happen at the same time.</p><p>Please wait for authorised hospital staff to confirm when you can leave.</p><hr><strong>Need an update?</strong><p>Contact your ward nurse or discharge coordinator for help.</p><button id="refresh" class="secondary">Refresh progress ↻</button></div><p class="demo-note">Only the case linked to your account is visible. This demonstration contains fictional data.</p></aside></div><section id="patient-insurance-ops" class="operations-panel help-section"></section><section id="patient-followup" class="operations-panel help-section"></section><section id="patient-case-history" class="operations-panel help-section"></section><section id="patient-preparation" class="operations-panel help-section"></section><section id="patient-assistant" class="operations-panel help-section"></section><section id="help-desk" class="operations-panel help-section"></section>`);
    await helpDesk();
    await patientInsuranceOps();
    await patientFollowup();
    await patientCaseHistory();
    await preparationPanel();
    patientAssistant();
    insuranceTimer=setInterval(async()=>{if(document.hidden)return;try{const {case:latest}=await api('/api/my-case');const notice=document.querySelector('#insurance-notice');if(notice)notice.innerHTML=insurancePanel(latest);}catch(error){if(error.status===401){clearInterval(insuranceTimer);showError(error);}}},30000);
    document.querySelector('#refresh').onclick = () => dashboard().catch(showError);
  }
}

function showError(error) {
  if(error.passwordChange)return location.replace('/change-password');
  if (error.status === 401) return login('Your session has ended. Please sign in again.');
  const old = document.querySelector('#page-error'); if (old) old.remove();
  const message = document.createElement('p'); message.id='page-error'; message.className='error'; message.role='alert'; message.textContent=error.message; main.prepend(message);
}

async function start() {
  if(location.pathname==='/admin'){sessionStorage.removeItem('adminHospital');sessionStorage.removeItem('adminHospitalName');}
  try {
    const me = await api('/api/me'); user=me.user; csrf=me.csrf;
    if(user.must_change){if(location.pathname!=='/change-password')return location.replace('/change-password');return changePasswordPage();}
    if (isStaff()?!visiblePages().some(([path])=>path===location.pathname):location.pathname!=='/patient') return location.replace(dashboardPath(user.role));
    await dashboard();
  }
  catch(error) { if(error.status===401) login(); else { login(); showError(error); } }
}
function newCaseForm() {
  const dialog=document.querySelector('#new-case-dialog');
  const local=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);
  dialog.innerHTML=`<div class="detail-heading"><h2 id="new-case-title">New discharge case</h2><button id="cancel-new-case" class="secondary">Cancel</button></div><form id="create-case" class="create-form"><p class="muted">Use fictional details only. This records a clinician's decision; it does not provide medical clearance. After creating the case, open Patient access to provision a verified patient or relative account.</p><label for="admission">Admission or encounter ID</label><input id="admission" name="admission" maxlength="40" pattern="[A-Za-z0-9-]+" required placeholder="IPD-2026-100301"><label for="patient-name">Patient display name</label><input id="patient-name" name="patientName" maxlength="80" required><label for="ward">Ward and bed</label><input id="ward" name="ward" maxlength="80" required><label for="payment">Payment pathway</label><select id="payment" name="payment"><option value="cash">Self pay</option><option value="insured">Cashless insured</option></select><label for="clinician">Authorising clinician</label><input id="clinician" name="clinician" maxlength="80" required><label for="cleared-at">Medical-clearance time</label><input id="cleared-at" name="clearedAt" type="datetime-local" value="${local}" required><label class="checkbox"><input name="confirmed" type="checkbox" required> I am recording clearance provided by an authorised clinician.</label><p class="error" role="alert"></p><button class="primary">Create case</button></form>`;
  document.querySelector('#cancel-new-case').onclick=()=>dialog instanceof HTMLDialogElement?dialog.close():location.assign('/coordinator/cases');
  document.querySelector('#create-case').onsubmit=async event=>{
    event.preventDefault();const f=event.target;const button=f.querySelector('button');button.disabled=true;
    try{await api('/api/cases',{method:'POST',body:JSON.stringify({id:f.admission.value,name:f.patientName.value,ward:f.ward.value,pathway:f.payment.value,clinician:f.clinician.value,cleared_at:new Date(f.clearedAt.value).toISOString(),confirmed:f.confirmed.checked})});if(dialog instanceof HTMLDialogElement)dialog.close();location.assign('/coordinator/cases');}
    catch(error){f.querySelector('.error').textContent=error.message;button.disabled=false;}
  };
  if(dialog instanceof HTMLDialogElement)dialog.showModal();
}

async function generalHelpDesk(host) {
  host.innerHTML=`<div class="section-heading"><div><p class="eyebrow">PATIENT SUPPORT</p><h2>${isStaff()?'Help desk inbox':'Message your coordinator'}</h2></div><button id="refresh-help" class="secondary">Refresh messages</button></div><p class="muted">Human help desk, not an automated chatbot. Replies appear here when a coordinator responds. This is not an emergency channel; contact ward staff directly for urgent or medical concerns. Use fictional messages in this demo.</p><div id="help-content"></div>`;
  const content=host.querySelector('#help-content');
  const conversation=async (path)=>{
    const data=await api(path);
    content.innerHTML=`<div class="message-list" aria-label="Conversation">${data.messages.length?data.messages.map(m=>`<article class="message ${['admin','coordinator'].includes(m.role)?'staff-message':''}"><strong>${m.role==='admin'?'Administrator':m.role==='coordinator'?'Coordinator':esc(m.sender)}</strong><time>${esc(new Date(m.created_at).toLocaleString())}</time><p>${esc(m.text)}</p></article>`).join(''):'<p class="muted">No messages yet. Ask about your discharge steps below.</p>'}</div><form id="message-form"><label for="message-text">${isStaff()?'Reply to this patient or relative':'Your question'}</label><textarea id="message-text" name="message" rows="3" maxlength="1000" required placeholder="Ask about a pending step or request an update"></textarea><p class="error" role="alert"></p><button class="primary inline-primary">Send message</button><span id="send-status" class="muted" role="status"></span></form>`;
    document.querySelector('#message-form').onsubmit=async event=>{
      event.preventDefault();const f=event.target;const button=f.querySelector('button');button.disabled=true;
      try{await api(path,{method:'POST',body:JSON.stringify({text:f.message.value})});await conversation(path);document.querySelector('#send-status').textContent=' Message saved. '+(isStaff()?'Your reply is available to the requester.':'Awaiting a coordinator reply.');}
      catch(error){f.querySelector('.error').textContent=error.message;button.disabled=false;}
    };
  };
  const load=async()=>{
    if(user.role==='patient')return conversation('/api/help');
    const {threads}=await api('/api/help/inbox');
    content.innerHTML=threads.length?`<div class="inbox">${threads.map(t=>`<button class="thread secondary" data-thread="${t.id}"><strong>${esc(t.case_id)} · ${esc(t.requester)}</strong><span>${t.state==='waiting'?'Awaiting coordinator reply':'Coordinator replied'} · ${esc(new Date(t.updated_at).toLocaleString())}</span></button>`).join('')}</div><div id="thread-tools"></div>`:'<p class="muted">No patient questions yet. Messages from linked patient accounts will appear here.</p>';
    host.querySelectorAll('[data-thread]').forEach(button=>button.onclick=async()=>{
      try{const threadId=button.dataset.thread;await conversation('/api/help/'+threadId);}catch(error){showError(error);}
    });
  };
  host.querySelector('#refresh-help').onclick=()=>load().catch(showError);
  await load();
}
async function operationalAlerts() {
  const host=document.querySelector('#operational-alerts'); if(!host)return;
  const render=async()=>{
    const data=await api('/api/insights');
    const largest=data.queues.filter(q=>q.eligible>0);const top=largest.length?largest.filter(q=>q.eligible===largest[0].eligible).map(q=>q.department).join(', '):null;
    host.innerHTML=`<div class="section-heading"><div><p class="eyebrow">OPERATIONAL ATTENTION</p><h2>Alerts and department queues</h2></div><button id="refresh-alerts" class="secondary">Refresh alerts</button></div><p class="muted">Rules and illustrative demo thresholds, not AI predictions or hospital service standards. Generated ${esc(new Date(data.generated_at).toLocaleString())}. Alerts may overlap for the same case.</p><p class="queue-leader"><strong>${top?'Largest eligible queue: '+esc(top):'No eligible tasks are currently queued'}</strong><span>A queue indicator, not proof of the hospital’s bottleneck. Blocked tasks are counted separately.</span></p><div class="table-scroll"><table class="case-table"><thead><tr><th>Department</th><th>Eligible and not started</th><th>In progress</th><th>On hold</th><th>Awaiting external insurer</th><th>Blocked by prerequisites</th></tr></thead><tbody>${data.queues.map(q=>`<tr><td>${esc(q.department)}</td><td>${q.eligible}</td><td>${q.processing}</td><td>${q.held}</td><td>${q.external||0}</td><td>${q.blocked}</td></tr>`).join('')}</tbody></table></div><details class="threshold-settings"><summary>Configure demo thresholds</summary><form id="threshold-form" class="threshold-form">${Object.entries(data.limits).map(([key,value])=>`<div><label for="limit-${key}">${({queue:'Eligible queue',processing:'Current work interval',hold:'On hold',stale:'No recent status event',total:'Since medical clearance'})[key]} in minutes</label><input id="limit-${key}" name="${key}" type="number" min="1" max="1440" value="${value}" required></div>`).join('')}<button class="secondary">Save thresholds</button><p class="error" role="alert"></p></form></details><div class="alert-list" aria-live="polite">${data.alerts.length?data.alerts.map(a=>`<article class="operational-alert"><div><strong>${esc(a.case_id)} · ${esc(a.department)}</strong><span>${esc(a.type)} · ${a.minutes} min / ${a.limit} min threshold</span></div><p>${esc(a.reason)}</p></article>`).join(''):'<p class="muted">No alerts meet the configured thresholds.</p>'}</div>`;
    document.querySelector('#refresh-alerts').onclick=()=>render().catch(showError);
    document.querySelector('#threshold-form').onsubmit=async event=>{
      event.preventDefault();const f=event.target;const button=f.querySelector('button');button.disabled=true;
      try{const limits=Object.fromEntries(Object.keys(data.limits).map(k=>[k,Number(f.elements.namedItem(k).value)]));await api('/api/insights',{method:'POST',body:JSON.stringify({limits})});await render();}
      catch(error){f.querySelector('.error').textContent=error.message;button.disabled=false;}
    };
  };await render();
}
function patientAssistant() {
  const host=document.querySelector('#patient-assistant');if(!host)return;
  host.innerHTML=`<p class="eyebrow">AUTOMATED SUPPORT</p><h2>Discharge assistant</h2><p class="muted">A rules-based chatbot for recorded progress and discharge-stage explanations. It is not an AI model, a clinician or a human coordinator. It cannot promise a departure time. Questions are not sent to an external AI service.</p><div class="quick-questions"><button class="secondary" data-question="What is my current progress?">My progress</button><button class="secondary" data-question="What is pharmacy clearance?">Explain pharmacy</button><button class="secondary" data-question="What is insurance authorisation?">Explain insurance</button><button class="secondary" data-question="When can I go home?">Discharge timing</button></div><div id="assistant-transcript" class="message-list" role="log" aria-label="Automated assistant conversation" aria-live="polite"><article class="message staff-message"><strong>Automated assistant</strong><p>I can explain common stages and check the latest stored progress for your linked case. For urgent or medical concerns, speak directly to ward staff.</p></article></div><form id="assistant-form"><label for="assistant-question">Ask the automated assistant</label><input id="assistant-question" name="question" maxlength="500" required placeholder="For example: what steps are pending?"><p class="error" role="alert"></p><button class="secondary">Ask assistant</button></form><p class="demo-note">This conversation clears when you refresh or leave the page. Use the human help desk below for a saved request.</p>`;
  const form=host.querySelector('#assistant-form');const transcript=host.querySelector('#assistant-transcript');
  const bubble=(name,text)=>{const article=document.createElement('article');article.className='message'+(name==='Automated assistant'?' staff-message':'');const strong=document.createElement('strong');strong.textContent=name;const p=document.createElement('p');p.textContent=text;article.append(strong,p);transcript.append(article);transcript.scrollTop=transcript.scrollHeight;return article;};
  const ask=async question=>{
    const button=form.querySelector('button');button.disabled=true;host.querySelectorAll('[data-question]').forEach(b=>b.disabled=true);form.querySelector('.error').textContent='';
    try{
      const result=await api('/api/assistant',{method:'POST',body:JSON.stringify({message:question})});
      bubble('You',question);const answer=bubble('Automated assistant',result.answer);const stamp=document.createElement('time');stamp.textContent='Checked '+new Date(result.as_of).toLocaleString()+' · Latest recorded task event '+new Date(result.latest_event).toLocaleString();answer.append(stamp);
      if(result.handoff){const handoff=document.createElement('button');handoff.className='secondary';handoff.textContent='Draft a question for the coordinator';handoff.onclick=()=>{const field=document.querySelector('#message-text');if(field){if(field.value.trim()){form.querySelector('.error').textContent='Your help-desk draft is not empty. Your question has not been copied or sent.';return;}field.value=question;field.focus();document.querySelector('#send-status').textContent=' Draft only. Press Send message to contact the coordinator.';}};answer.append(handoff);}
      form.question.value='';transcript.scrollTop=transcript.scrollHeight;
    }catch(error){form.querySelector('.error').textContent=error.message;}
    finally{button.disabled=false;host.querySelectorAll('[data-question]').forEach(b=>b.disabled=false);}
  };
  form.onsubmit=event=>{event.preventDefault();ask(form.question.value);};
  host.querySelectorAll('[data-question]').forEach(button=>button.onclick=()=>ask(button.dataset.question));
}
async function simulator() {
 const host=document.querySelector('#what-if');if(!host)return;
 const config=await api('/api/simulation');const d=config.defaults;
 host.innerHTML=`<div class="section-heading"><div><p class="eyebrow">EXPLORE AN OPERATIONAL CHANGE</p><h2>What-if simulator</h2></div><span class="pathway">Isolated from live records</span></div><p class="muted">Compare the same active backlog under baseline and proposed capacity. Deterministic estimates from your assumptions, not validated predictions, staff assignments or departure promises.</p><form id="simulation-form"><div class="table-scroll"><table class="case-table model-table"><thead><tr><th>Stage</th><th>Baseline operators</th><th>Assumed service or remaining minutes</th></tr></thead><tbody>${config.stages.map((stage,i)=>`<tr><th scope="row">${esc(stage)}</th><td><label class="sr-only" for="capacity-${i}">${esc(stage)} baseline operators</label><input id="capacity-${i}" name="capacity-${i}" type="number" min="${Math.max(1,config.in_progress[i])}" max="10" value="${d.capacity[i]}" required></td><td><label class="sr-only" for="service-${i}">${esc(stage)} assumed minutes</label><input id="service-${i}" name="service-${i}" type="number" min="1" max="240" value="${d.minutes[i]}" required></td></tr>`).join('')}</tbody></table></div><div class="simulation-inputs"><div><label for="insurer-time">External insurer response in minutes</label><input id="insurer-time" name="insurer" type="number" min="0" max="1440" value="${d.insurer_minutes}" required></div><div><label for="hold-release">Assumed hold release after minutes</label><input id="hold-release" name="hold" type="number" min="0" max="1440" value="${d.hold_minutes}" required></div><div><label for="ready-cutoff">Count cases ready within minutes</label><input id="ready-cutoff" name="cutoff" type="number" min="1" max="2880" value="${d.cutoff_minutes}" required></div><div><label for="scenario-stage">Department to change</label><select id="scenario-stage" name="stage">${config.stages.map((stage,i)=>`<option value="${i}" ${i===2?'selected':''}>${esc(stage)}</option>`).join('')}</select></div><div><label for="proposed-capacity">Proposed operators</label><input id="proposed-capacity" name="proposed" type="number" min="${Math.max(1,config.in_progress[2])}" max="10" value="${Math.min(10,d.capacity[2]+1)}" required></div></div><p class="muted">${config.active_cases} active cases were available when this form loaded. Each run takes a fresh snapshot. Completed tasks are skipped. Documentation and pharmacy can run in parallel.</p><details class="model-assumptions"><summary>Read model assumptions and limitations</summary><ul><li>No new cases arrive during the simulation. Operators remain available for the entire run; no breaks or shift changes are modelled.</li><li>Durations are synthetic assumptions. For an already in-progress task, the entered duration is its assumed remaining work, not the recorded elapsed time.</li><li>Work already in progress starts at time zero and is not interrupted. Capacity cannot fall below current in-progress work.</li><li>Tasks are scheduled in eligibility order with reproducible ties. Initial pending queues are ordered by clearance time; original queue-entry history is not fully reconstructed.</li><li>The insurance stage models internal desk service followed by a separate external response delay. Extra desk operators do not reduce that external delay.</li><li>Held tasks are hypothetically released after the entered interval. A real hold may persist indefinitely. No simulation releases a real hold.</li><li>Outputs measure future time from this run until tracked tasks finish. They do not measure clinical readiness, actual departure or available beds. This is a workflow simulator, not a calibrated digital twin.</li></ul></details><p class="error" role="alert"></p><button class="primary simulation-run">Compare scenarios</button></form><div id="simulation-results" aria-live="polite"></div>`;
 const form=host.querySelector('#simulation-form');const result=host.querySelector('#simulation-results');
 form.elements.stage.onchange=()=>{const i=Number(form.elements.stage.value);form.elements.proposed.min=Math.max(1,config.in_progress[i]);form.elements.proposed.value=Math.min(10,Number(form.elements.namedItem('capacity-'+i).value)+1);};
 // Results remain visible only for the inputs used to generate them.
 form.addEventListener('input',()=>{result.innerHTML='<p class="muted">Inputs changed. Run the comparison again to see matching results.</p>';});
 form.onsubmit=async event=>{
  event.preventDefault();const controls=[...form.querySelectorAll('input,select,button')];controls.forEach(control=>control.disabled=true);form.querySelector('.error').textContent='';
  const val=name=>Number(form.elements.namedItem(name).value);
  try{
   const data=await api('/api/simulation',{method:'POST',body:JSON.stringify({baseline:{capacity:config.stages.map((_,i)=>val('capacity-'+i)),minutes:config.stages.map((_,i)=>val('service-'+i)),insurer_minutes:val('insurer'),hold_minutes:val('hold'),cutoff_minutes:val('cutoff')},stage:val('stage'),proposed_capacity:val('proposed')})});
   if(!data.count){result.innerHTML='<div class="empty-state"><h3>No active cases to simulate</h3><p>Create a fictional case or use a case with incomplete tasks.</p></div>';return;}
   result.innerHTML=simulationResults(data,config.stages);
  }catch(error){result.innerHTML='';form.querySelector('.error').textContent=error.message;}
  finally{controls.forEach(control=>control.disabled=false);}
 };
}

